INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES 
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Paciente masculino, 68 anos, tabagista e hipertenso, submetido a uma hemicolectomia direita por via laparotômica devido a adenocarcinoma de cólon. No 3º dia de pós-operatório (DPO), apresenta quadro de dispneia súbita, dor torácica pleurítica à direita e taquicardia (FC: 115 bpm). Ao exame físico, apresenta-se taquipneico (FR: 28 irpm), PA: 130/80 mmHg, saturação de oxigênio de 89% em ar ambiente. A ausculta pulmonar revela murmúrio vesicular presente e simétrico, sem ruídos adventícios. Panturrilhas livres. ECG mostra apenas taquicardia sinusal. Com base na principal suspeita clínica, a conduta inicial mais adequada é:", "options": {"a": "Realizar radiografia de tórax e iniciar antibioticoterapia para pneumonia hospitalar.", "b": "Solicitar dímero-D e, se positivo, iniciar anticoagulação empírica com heparina.", "c": "Solicitar angiotomografia de tórax após estabilização e avaliação de risco pelo escore de Wells.", "d": "Indicar pleurocentese de alívio por suspeita de pneumotórax hipertensivo.", "e": "Realizar ecocardiograma transtorácico e dosar troponinas para afastar infarto agudo do miocárdio."}, "answer": "c", "rationale": "O quadro de dispneia súbita e taquicardia no pós-operatório de grande cirurgia abdominal em paciente com fatores de risco é altamente sugestivo de Tromboembolismo Pulmonar (TEP). A conduta deve ser guiada pela probabilidade clínica (Escore de Wells). Se a probabilidade for moderada/alta, o exame padrão-ouro para confirmação é a Angiotomografia de Tórax.", "option_rationales": {"a": "Incorreta. O murmúrio vesicular normal e o início súbito tornam a pneumonia menos provável.", "b": "Incorreta. O dímero-D tem baixo valor preditivo em pós-operatórios recentes, pois costuma estar elevado pelo trauma cirúrgico.", "c": "Correta. É o protocolo para diagnóstico de TEP em pacientes estáveis.", "d": "Incorreta. Não há sinais clínicos de pneumotórax (hipertimpanismo ou ausência de murmúrio).", "e": "Incorreta. Embora o IAM seja um diferencial, a clínica de dor pleurítica e hipóxia súbita direciona mais para TEP."}, "difficulty": "dificil", "tags": ["Cirurgia Geral", "Pós-operatório", "TEP", "Complicações Cardiovasculares"]}', 0, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Paciente feminina, 45 anos, obesa, submetida a colecistectomia videolaparoscópica de urgência por colecistite aguda. No 2º DPO, apresenta-se febril (38,2°C), com náuseas e dor abdominal difusa leve. Ao exame físico: abdome distendido, timpanismo aumentado, ruídos hidroaéreos ausentes. Nega eliminação de flatos ou fezes desde a cirurgia. Radiografia de abdome mostra alças de delgado e cólon uniformemente dilatadas, com gás presente no reto. Ausência de sinais de peritonismo. Diante do quadro clínico apresentado, a melhor conduta inicial neste caso é:", "options": {"a": "Indicar laparotomia exploradora imediata por suspeita de lesão iatrogênica de via biliar.", "b": "Prescrever neostigmina endovenosa para acelerar o trânsito intestinal.", "c": "Manter jejum, hidratação venosa, correção de distúrbios eletrolíticos e deambulação precoce.", "d": "Solicitar tomografia de abdome com contraste oral para descartar obstrução mecânica por bridas.", "e": "Iniciar antibioticoterapia de amplo escopo para tratamento de abscesso intra-abdominal precoce."}, "answer": "c", "rationale": "O quadro é clássico de Íleo Adinamia (paralisia intestinal pós-operatória fisiológica). A presença de dilatação uniforme e gás no reto sugere que não há obstrução mecânica. O manejo é conservador com suporte clínico, esperando a resolução espontânea, que geralmente ocorre em 48-72h.", "option_rationales": {"a": "Incorreta. Laparotomia não é indicada sem sinais de peritonite ou evidência clara de complicação cirúrgica.", "b": "Incorreta. A neostigmina é usada na Pseudo-obstrução de cólon (Síndrome de Ogilvie) e não no íleo metabólico/fisiológico comum.", "c": "Correta. Suporte clínico e estímulo à deambulação são os pilares do tratamento.", "d": "Incorreta. A radiografia já forneceu dados suficientes para o diagnóstico de íleo adinâmico inicial; a TC seria reservada se houvesse piora rápida ou dúvida persistente.", "e": "Incorreta. A febre no 2º DPO após colecistite pode ser inflamatória ou por atelectasia; náuseas e distensão indicam íleo e não necessariamente infecção ativa grave."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Íleo Adinâmico", "Complicações Gastrointestinais"]}', 1, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente de 72 anos, em 5º DPO de gastrectomia total por câncer gástrico, apresenta saída de secreção serossanguinolenta abundante pela ferida operatória laparotômica após esforço de tosse. Ao exame da ferida, não há sinais flogísticos ou saída de pus, mas observa-se abaulamento local. O paciente está estável hemodinamicamente e com abdome indolor à palpação profunda. A suspeita diagnóstica imediata e a conduta correta são:", "options": {"a": "Infecção de sítio cirúrgico superficial; abertura da pele e drenagem no leito.", "b": "Evisceração completa; retorno imediato ao centro cirúrgico para lavagem e fechamento por planos.", "c": "Evisceração incompleta (deiscência de aponeurose); proteção da ferida com compressas úmidas e programação de reforço de sutura no centro cirúrgico.", "d": "Abscesso de parede; compressas quentes e antibioticoterapia oral.", "e": "Hérnia incisional tardia; uso de cinta abdominal e acompanhamento ambulatorial."}, "answer": "c", "rationale": "A saída de secreção serossanguinolenta (líquido cor de ''água de carne'') em grande quantidade após esforço é o sinal patognomônico de deiscência de aponeurose (evisceração incompleta). O conteúdo abdominal pode estar contido apenas pela pele. Exige proteção da área e correção cirúrgica para evitar evisceração completa.", "option_rationales": {"a": "Incorreta. A secreção serossanguinolenta maciça não é típica de infecção superficial.", "b": "Incorreta. Evisceração completa envolve a saída de vísceras para o exterior da pele.", "c": "Correta. É o diagnóstico e manejo corretos para deiscência aponeurótica.", "d": "Incorreta. Abscessos apresentam pus e sinais inflamatórios locais (dor, calor, rubor).", "e": "Incorreta. O termo hérnia incisional é usado para deiscências que ocorrem tardiamente, após a cicatrização da pele."}, "difficulty": "dificil", "tags": ["Cirurgia Geral", "Pós-operatório", "Deiscência", "Complicações da Parede Abdominal"]}', 2, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Paciente de 58 anos submetida a tireoidectomia total por bócio multinodular volumoso. Nas primeiras 6 horas de pós-operatório na sala de recuperação, desenvolve agitação, estridor inspiratório e abaulamento cervical progressivo e tenso. Apresenta saturação de 91% em O2 por cateter nasal e taquicardia. O diagnóstico provável para este quadro agudo é:", "options": {"a": "Crise tireotóxica pós-operatória.", "b": "Hematoma cervical expansivo com compressão de vias aéreas.", "c": "Hipocalcemia aguda por lesão de paratireoides.", "d": "Lesão bilateral do nervo laríngeo recorrente.", "e": "Traqueomalácia por compressão crônica do bócio."}, "answer": "b", "rationale": "O hematoma cervical é uma emergência cirúrgica clássica após cirurgias cervicais. O acúmulo de sangue em espaço restrito causa compressão venosa e edema de glote rápido, levando à obstrução de via aérea.", "option_rationales": {"a": "Incorreta. A crise tireotóxica causa hipertensão, febre alta e arritmias, mas não abaulamento cervical tenso.", "b": "Correta. Quadro clínico típico de hematoma compressivo.", "c": "Incorreta. A hipocalcemia causa parestesias e sinal de Chvostek/Trousseau, aparecendo geralmente após 24-48h.", "d": "Incorreta. Causaria afonia e estridor, mas não abaulamento cervical tenso.", "e": "Incorreta. É uma possibilidade tardia ou imediata após extubação, mas o abaulamento cervical direciona para hematoma."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Hematoma", "Emergência Cirúrgica"]}', 3, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um jovem de 24 anos, vítima de trauma abdominal fechado, foi submetido a esplenectomia de urgência. No 4º DPO, evolui com febre de 38,5°C, tosse produtiva e redução do murmúrio vesicular em base esquerda. Frequentemente relata dor ao respirar profundamente no local da incisão abdominal alta, o que o faz realizar respirações curtas. O raio-x de tórax evidencia opacidade linear em base de pulmão esquerdo com elevação da cúpula diafragmática ipsilateral. A causa mais provável para a febre e o achado radiológico é:", "options": {"a": "Pneumonia nosocomial bacteriana.", "b": "Abscesso subfrênico esquerdo pós-esplenectomia.", "c": "Atelectasia pulmonar por hipoventilação álgica.", "d": "Embolia pulmonar maciça.", "e": "Efuração pleural traumática não drenada."}, "answer": "c", "rationale": "A atelectasia é a causa mais comum de febre nas primeiras 48-72h (e pode persistir) no pós-operatório, especialmente em cirurgias abdominais altas onde a dor dificulta a expansão pulmonar efetiva e a tosse.", "option_rationales": {"a": "Incorreta. Embora seja um diferencial, a imagem de opacidade linear e elevação do diafragma é muito característica de atelectasia.", "b": "Incorreta. Abscessos costumam aparecer mais tarde (5-7 DPO) e com quadro tóxico mais evidente.", "c": "Correta. Diagnóstico mais frequente e compatível com a radiografia descrita.", "d": "Incorreta. TEP não costuma causar febre alta e opacidades lineares típicas como as de atelectasia.", "e": "Incorreta. O derrame (efusão) teria imagem de velamento de seio costofrênico e não opacidade linear."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Atelectasia", "Febre Pós-operatória"]}', 4, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em um paciente submetido a cirurgia colorretal eletiva, qual dos seguintes achados clínicos no 5º DPO deve levantar a maior suspeita de deiscência de anastomose intestinal antes mesmo da exteriorização de fezes pelo dreno?", "options": {"a": "Íleo adinâmico persistente e distensão abdominal.", "b": "Febre baixa (37,8°C) e leucocitose leve.", "c": "Taquicardia sustentada, desorientação súbita ou sensação de ''morte iminente''.", "d": "Aumento do débito líquido serossanguinolento pelo dreno.", "e": "Dificuldade de controle glicêmico em paciente diabético."}, "answer": "c", "rationale": "A taquicardia é frequentemente o primeiro sinal de sepse abdominal por deiscência de anastomose. Alterações do sensório ou instabilidade hemodinâmica inexplicada no 5-7 DPO devem sempre alertar para vazamento intestinal.", "option_rationales": {"a": "Incorreta. Pode ocorrer por irritação peritoneal, mas é menos específica que a taquicardia.", "b": "Incorreta. São achados muito inespecíficos no pós-operatório.", "c": "Correta. Sinais precoces de sepse cirúrgica.", "d": "Incorreta. Serossanguinolento é o padrão normal esperado.", "e": "Incorreta. Ocorre em qualquer processo inflamatório ou infeccioso."}, "difficulty": "dificil", "tags": ["Cirurgia Geral", "Pós-operatório", "Deiscência", "Sutura Intestinal"]}', 5, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um homem de 50 anos é submetido a uma herniorrafia inguinal bilateral. Nas primeiras 12 horas pós-op, queixa-se de dor em hipogástrio intensa e incapacidade de urinar. Ao exame físico, nota-se massa palpável, firme e dolorosa na região suprapúbica, com macicez à percussão. O paciente está agitado e hipertenso (PA 160/95 mmHg). A abordagem inicial mais rápida e segura neste caso é:", "options": {"a": "Administrar analgésicos opioides para alívio da dor e aguardar micção espontânea.", "b": "Solicitar ultrassonografia de rins e vias urinárias para descartar hidronefrose.", "c": "Realizar cateterismo vesical de alívio imediato.", "d": "Prescrever bloqueadores alfa-adrenérgicos para relaxar o esfíncter vesical.", "e": "Indicar reintervenção por suspeita de lesão iatrogênica de ureter durante a cirurgia."}, "answer": "c", "rationale": "O quadro é típico de retenção urinária aguda (bexigoma), complicação comum após cirurgias inguinais e pélvicas devido ao trauma local, anestesia e dor. O tratamento imediato é a drenagem da urina.", "option_rationales": {"a": "Incorreta. Opioides podem piorar a retenção por interferirem no reflexo detrusor.", "b": "Incorreta. O diagnóstico é clínico e a demora no tratamento causa sofrimento desnecessário.", "c": "Correta. Resolutivo e alivia a dor e a hipertensão reativa imediatamente.", "d": "Incorreta. Agem de forma lenta e não resolvem a retenção aguda instalada.", "e": "Incorreta. Lesão de ureter causaria anúria ou urinoma tardio, não bexigoma palpável tenso."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Retenção Urinária", "Complicações Geniturinárias"]}', 6, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Paciente de 65 anos, obeso, hipertenso, submetido a laparotomia por peritonite fecal após perfuração diverticular. No 1º DPO, apresenta-se com oligúria (débito urinário de 0,3 ml/kg/h nas últimas 6h), pressão inspiratória de pico elevada no ventilador e distensão abdominal importante. Ao medir a pressão intra-abdominal (PIA) via cateter vesical, obtém-se o valor de 24 mmHg. Qual a conduta imediata preconizada para este paciente considerando a Síndrome de Compartimento Abdominal?", "options": {"a": "Apenas observação e restrição hídrica rigorosa.", "b": "Descompressão cirúrgica de urgência (laparotomia descompressiva).", "c": "Iniciar hemodiálise para tratamento da insuficiência renal aguda.", "d": "Utilizar diuréticos de alça para reduzir o edema de alças.", "e": "Posicionar o paciente em Trendelenburg para melhorar o retorno venoso."}, "answer": "b", "rationale": "Hipertensão intra-abdominal (HIA) grau IV (> 25 mmHg) ou grau III associada a disfunção orgânica (como oligúria e dificuldade ventilatória) define a Síndrome de Compartimento Abdominal, cuja única solução definitiva é a descompressão.", "option_rationales": {"a": "Incorreta. A conduta expectante levará à falência múltipla de órgãos.", "b": "Correta. Padrão-ouro para tratamento da síndrome instalada com disfunção.", "c": "Incorreta. A causa da insuficiência renal é a compressão mecânica dos rins e redução do débito cardíaco, não resolúvel primariamente pela diálise.", "d": "Incorreta. Diuréticos não reduzem a pressão mecânica aguda e podem piorar a perfusão.", "e": "Incorreta. O Trendelenburg aumentaria a pressão cranial e pioraria a ventilação."}, "difficulty": "dificil", "tags": ["Cirurgia Geral", "Pós-operatório", "SCA", "Síndrome de Compartimento Abdominal"]}', 7, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Paciente submetido a esofagectomia transhiatal por câncer de esôfago distal. No 7º DPO, nota-se saída de líquido leitoso em grande quantidade pelo dreno pleural à direita (cerca de 1.200 ml/dia). O líquido tem concentração de triglicerídeos de 180 mg/dL e presença de quilomícrons. Com base no diagnóstico de quilotórax, a abordagem inicial conservadora deve incluir:", "options": {"a": "Antibioticoterapia de amplo espectro por suspeita de empiema.", "b": "Dieta parenteral total exclusiva ou dieta enteral com triglicerídeos de cadeia média (TCM).", "c": "Pleurodese química imediata com talco.", "d": "Reposição volêmica com coloides e retorno imediato à dieta oral livre.", "e": "Ligadura cirúrgica do ducto torácico em caráter de urgência máxima."}, "answer": "b", "rationale": "O tratamento inicial do quilotórax é conservador na maioria dos casos, visando reduzir a produção de quilo. O TCM é absorvido diretamente pela veia porta, saltando a drenagem linfática do ducto torácico.", "option_rationales": {"a": "Incorreta. O quilo é estéril inicialmente; o empiema teria pus e bactérias.", "b": "Correta. Base do tratamento nutricional conservador.", "c": "Incorreta. Reservada para casos falhos ou neoplásicos tardios.", "d": "Incorreta. Dieta rica em gordura de cadeia longa aumentaria o débito da fístula drenada.", "e": "Incorreta. A cirurgia é indicada se houver alto débito persistente (> 1,5L/dia em adultos) ou falha do conservador após 1 a 2 semanas."}, "difficulty": "moderada", "tags": ["Cirurgia Geral", "Pós-operatório", "Quilotórax", "Fístula Quilosa"]}', 8, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em uma cirurgia de grande porte, o anestesista relata subida súbita da concentração de CO2 expirado (EtCO2), taquicardia persistente e rigidez muscular generalizada no paciente. Ao checar a temperatura axilar, observa-se 39,8°C. Qual a medicação de escolha que deve ser administrada imediatamente para reverter este quadro de hipertermia maligna?", "options": {"a": "Dantrolene sódico.", "b": "Sulfato de Magnésio.", "c": "Dipirona endovenosa.", "d": "Gluconato de Cálcio.", "e": "Succinilcolina bólus."}, "answer": "a", "rationale": "A hipertermia maligna é uma complicação farmacogenética grave desencadeada por anestésicos inalatórios ou succinilcolina. O dantrolene é o único antídoto específico, agindo no canal de rianodina para reduzir o cálcio intracitoplasmático muscular.", "option_rationales": {"a": "Correta. Única droga eficaz para reverter a fisiopatologia da crise.", "b": "Incorreta. Não tem ação no mecanismo central da doença.", "c": "Incorreta. Antitérmicos comuns não funcionam, pois a produção de calor é periférica e metabólica muscular excessiva.", "d": "Incorreta. O cálcio alto dentro da célula é o problema; cálcio extra poderia piorar a contração se houver distúrbios de membrana.", "e": "Incorreta. A succinilcolina é um dos gatilhos da doença; administrá-la seria fatal."}, "difficulty": "facil", "tags": ["Anestesiologia", "Complicação Transoperatória", "Hipertermia Maligna", "Farmacologia"]}', 9, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Uma paciente de 35 anos, no 1º DPO de uma histerectomia abdominal, apresenta taquicardia, tremores, sudorese profusa e hipertensão. Relata que faz uso de bebida alcoólica diariamente em grande quantidade e que parou abruptamente no dia da internação. O quadro sugere abstinência alcoólica. No manejo desta complicação pós-operatória, a droga de primeira escolha para o controle da agitação psicomotora é:", "options": {"a": "Haloperidol.", "b": "Clorpromazina.", "c": "Benzodiazepínicos (ex: Diazepam ou Lorazepam).", "d": "Propofol em infusão contínua.", "e": "Fenitoína."}, "answer": "c", "rationale": "Os benzodiazepínicos são o pilar do tratamento da síndrome de abstinência e do delirium tremens, agindo nos receptores GABA que estão hipoestimulados pela retirada do álcool.", "option_rationales": {"a": "Incorreta. Isoladamente, pode baixar o limiar convulsivo, o que é perigoso na abstinência.", "b": "Incorreta. Pelo mesmo motivo do haloperidol e risco de hipotensão.", "c": "Correta. Tratamento padrão-ouro para segurança e eficácia.", "d": "Incorreta. Reservado para casos de falha terapêutica em ambiente de UTI com ventilação.", "e": "Incorreta. Indicada apenas se houver convulsões não resolvidas por Benzodiazepínicos."}, "difficulty": "media", "tags": ["Clínica Cirúrgica", "Pós-operatório", "Abstinência Alcoólica", "Complicações Psiquiátricas"]}', 10, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No 4º DPO de uma duodenopancreatectomia (cirurgia de Whipple), observa-se saída de líquido límpido pelo dreno colocado adjacente à anastomose pancreatojejunal. A dosagem da amilase nesse líquido revela um valor de 4.500 U/L (nível sérico é de 80 U/L). O volume drenado é de 150 ml/dia. O paciente está afebril e sem dores abdominais importantes. Com base na classificação atual (ISGPS), este achado define:", "options": {"a": "Fístula pancreática clinicamente relevante (Grau B).", "b": "Fístula pancreática Grau C (catastrófica).", "c": "Vazamento bioquímico (antigo Grau A).", "d": "Pancreatite aguda pós-operatória.", "e": "Abscesso pancreático precoce."}, "answer": "c", "rationale": "Pela classificação de 2016 da ISGPS, a saída de amilase > 3x o limite superior do soro pelo dreno no 3º DPO ou posterior, sem repercussão clínica no paciente, é chamada de ''fuga bioquímica'' (biochemical leak) e não é considerada uma fístula pancreática verdadeira em termos de complicação cirúrgica impactante.", "option_rationales": {"a": "Incorreta. O Grau B exige mudança de conduta (manter dreno > 3 semanas, drenagem por radiologia, etc) ou sinais inflamatórios.", "b": "Incorreta. O Grau C exige reoperação ou causa falência orgânica.", "c": "Correta. Atende aos critérios de amilase elevada no dreno em paciente assintomático.", "d": "Incorreta. Definida por dor e amilase sérica elevada, não apenas no dreno.", "e": "Incorreta. Não há sinais de infecção ou coleção organizada."}, "difficulty": "moderada", "tags": ["Cirurgia Geral", "Pós-operatório", "Fístula Pancreática", "Pâncreas"]}', 11, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Paciente submetido a ressecção de tumor de retroperitônio volumoso, com perda sanguínea estimada de 1,5 litro. Recebeu 4 unidades de concentrado de hemácias no peroperatório. No pós-operatório imediato na UTI, desenvolve hipoxemia severa (PaO2/FiO2 < 200), infiltrado pulmonar bilateral difuso na radiografia e pressão de oclusão de artéria pulmonar (POAP) normal (12 mmHg). Ausência de sinais de sobrecarga hídrica. Qual a complicação pulmonar pós-transfusional mais provável?", "options": {"a": "TACO (Sobrecarga circulatória associada à transfusão).", "b": "TRALI (Lesão pulmonar aguda relacionada à transfusão).", "c": "Pneumonia aspirativa.", "d": "Reação hemolítica tardia.", "e": "Infarto pulmonar por microembolia."}, "answer": "b", "rationale": "A TRALI é uma lesão imuno-mediada (por anticorpos anti-HLA do doador) que causa edema pulmonar não cardiogênico (permeabilidade aumentada). A POAP normal descarta o componente hidrostático (TACO).", "option_rationales": {"a": "Incorreta. A POAP estaria elevada (> 18 mmHg) na sobrecarga hídrica.", "b": "Correta. Diagnóstico de exclusão compatível com POAP normal e tempo pós-transfusional.", "c": "Incorreta. Geralmente apresenta febre e história de vômito ou depressão do sensório.", "d": "Incorreta. Causaria icterícia e queda de hemoglobina, não edema pulmonar agudo.", "e": "Incorreta. Não explicaria o infiltrado bilateral difuso típico de SARA."}, "difficulty": "moderada", "tags": ["Terapia Intensiva", "Complicações Pós-operatórias", "Transfusão", "TRALI"]}', 12, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Uma mulher de 60 anos, obesa, no 6º DPO de uma laparotomia exploradora, queixa-se de dor intensa na perna esquerda. Ao exame, apresenta edema importante em todo o membro inferior esquerdo, cianose leve das extremidades e empastamento de panturrilha com sinal de Homans positivo. Foi solicitada Ultrassonografia Doppler que confirmou Trombose Venosa Profunda (TVP) íleo-femoral. Qual a conduta inicial recomendada considerando que a paciente foi operada há 6 dias?", "options": {"a": "Fibrinólise sistêmica imediata para evitar embolia pulmonar.", "b": "Trombectomia cirúrgica de urgência.", "c": "Anticoagulação plena com Heparina de Baixo Peso Molecular ou Heparina Não Fracionada.", "d": "Colocação de filtro de veia cava superior por contraindicação de anticoagulação.", "e": "Apenas compressão elástica e deambulação precoce."}, "answer": "c", "rationale": "Apesar da cirurgia recente (6 dias), a contraindicação para anticoagulação plena costuma ser absoluta apenas nas primeiras 24-48h, a menos que haja sangramento ativo. A anticoagulação é o tratamento padrão para TVP para evitar progressão e TEP.", "option_rationales": {"a": "Incorreta. Fibrinólise é formalmente contraindicada em pós-operatórios recentes (alto risco de sangramento fatal no sítio cirúrgico).", "b": "Incorreta. Raramente executada, reservada para casos de Phlegmasia Cerulea Dolens refratária.", "c": "Correta. Tratamento indicado para TVP.", "d": "Incorreta. O filtro é para quando a anticoagulação é proibida ou falhou. No 6º DPO de cirurgia abdominal não hemorrágica, geralmente pode-se anticoagular.", "e": "Incorreta. Conduta insuficiente para evitar TEP."}, "difficulty": "media", "tags": ["Cirurgia Vascular", "Pós-operatório", "TVP", "Anticoagulação"]}', 13, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente tabagista, submetido a correção de hérnia de parede abdominal com uso de tela de polipropileno, apresenta drenagem de líquido límpido amarelado e indolor pela ferida no 10º DPO. Não há febre ou hiperemia da ferida. O cirurgião diagnostica seroma de grande volume. Qual a conduta mais adequada para manejar o seroma para evitar infecção secundária da tela?", "options": {"a": "Aspiração com agulha fina sob técnica asséptica apenas se houver tensão ou dor.", "b": "Abertura ampla da ferida com remoção imediata da tela por risco de contaminação.", "c": "Prescrever antibióticos de amplo espectro profilaticamente por 14 dias.", "d": "Realizar curativos compressivos aspirando o líquido diariamente no chuveiro.", "e": "Indicar reoperação para colocação de dreno de sucção fechado."}, "answer": "a", "rationale": "Seromas pequenos podem ser observados. Seromas grandes ou tensos devem ser aspirados com agulha para alívio. Abertura da pele deve ser evitada para não expor a tela ao ambiente externo, o que aumentaria o risco de colonização bacteriana.", "option_rationales": {"a": "Correta. Manobra conservadora e segura para evitar infecção.", "b": "Incorreta. Tela só é removida se houver infecção franca e incurável (extrusão ou Biofilme).", "c": "Incorreta. Antibiótico não trata coleção líquida estéril.", "d": "Incorreta. Manipulação frequente no banho aumenta o risco de introduzir bactérias.", "e": "Incorreta. Reoperação é excessiva; a punção costuma resolver."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Seroma", "Tela Cirúrgica"]}', 14, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em pacientes submetidos a cirurgia cardíaca com circulação extracorpórea (CEC), uma complicação frequente é o sangramento excessivo no pós-operatório imediato. Além da hemostasia cirúrgica, qual a causa hematológica mais comum de sangramento relacionada especificamente ao uso da CEC?", "options": {"a": "Deficiência de Fator VIII (Hemofilia A adquirida).", "b": "Disfunção plaquetária e consumo de fatores de coagulação pelo circuito.", "c": "Sobrecarga de Vitamina K.", "d": "Inibição do fator Xa pela protamina.", "e": "Ativação exagerada das plaquetas pela hipotermia."}, "answer": "b", "rationale": "O contato do sangue com as superfícies não endoteliais do circuito de CEC causa ativação e disfunção plaquetária significativa, além de hemólise rala e consumo de fibrinogênio. É o chamado ''distúrbio hemorrágico da CEC''.", "option_rationales": {"a": "Incorreta. Não tem relação direta com o trauma da CEC.", "b": "Correta. Causa fisiopatológica básica do sangramento na CEC.", "c": "Incorreta. Vitamina K é pró-coagulante.", "d": "Incorreta. A protamina é o antídoto da heparina; o excesso de protamina (e não a falta) pode ter efeito anticoagulante leve, mas não via Xa.", "e": "Incorreta. A hipotermia geralmente inibe a função plaquetária."}, "difficulty": "moderada", "tags": ["Cirurgia Cardíaca", "Pós-operatório", "Sangramento", "CEC"]}', 15, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente de 45 anos, obeso, realizou uma cirurgia bariátrica (Bypass gástrico em Y-de-Roux). No 3º DPO, refere dor intensa em região de panturrilha direita e dificuldade para deambular. No exame físico, há edema assimétrico de membros inferiores (> 3cm em perna direita), dor à palpação profunda da panturrilha e taquicardia leve. Não apresenta queixas respiratórias. De acordo com o escore de Wells, qual o próximo passo obrigatório?", "options": {"a": "Realizar dímero-D; se negativo, afasta TVP.", "b": "Iniciar anticoagulação profilática e observar por 24 horas.", "c": "Solicitar eco-Doppler venoso de membros inferiores.", "d": "Encaminhar para cintilografia de ventilação-perfusão preventiva.", "e": "Solicitar Angiotomografia de abdome para descartar fístula na anastomose."}, "answer": "c", "rationale": "Com edema assimétrico, dor à palpação e cirurgia recente (pós-op de bariátrica é alto risco), a probabilidade clínica de TVP é alta. O Doppler é o exame de eleição para confirmar o diagnóstico em território infra-inguinal.", "option_rationales": {"a": "Incorreta. Dímero-D pós-cirúrgico é sempre alto, perdendo utilidade diagnóstica.", "b": "Incorreta. Ele já deveria estar em profilaxia; se há suspeita, precisa de diagnóstico para iniciar dose terapêutica.", "c": "Correta. Conduta diagnóstica padrão.", "d": "Incorreta. Exame para TEP, não para TVP de membro.", "e": "Incorreta. A dor na panturrilha e o edema são específicos para sistema venoso."}, "difficulty": "facil", "tags": ["Cirurgia Bariátrica", "Pós-operatório", "TVP", "Escore de Wells"]}', 16, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Paciente submetido a retocoliteprouctectomia total com reservatório ileal devido a Retocolite Ulcerativa. No 4º DPO, desenvolve quadro de náuseas importantes, vômicos esverdeados e parada de eliminação de gazes pela ileostomia. Ao exame físico: abdome distendido, ruidoso (RHA aumentados e em timbre metálico) e doloroso à palpação difusa, sem peritonite. Raios-x de abdome mostram níveis hidroaéreos e distensão central de alças de delgado. Qual o diagnóstico e a conduta inicial?", "options": {"a": "Íleo adinâmico; dieta zero e hidratação.", "b": "Obstrução mecânica de delgado (provável brida precoce ou torção); descompressão com sonda nasogástrica, jejum e avaliação seriada.", "c": "Deiscência da bolsa ileal; laparotomia imediata.", "d": "Isquemia mesentérica arterial; angiotomografia urgente.", "e": "Enterite por Clostridioides difficile; vancomicina oral."}, "answer": "b", "rationale": "A presença de RHA aumentados (metálicos) e vômitos biliosos diferencia a obstrução mecânica (delgado) do íleo adinâmico (onde os RHA estariam ausentes). No pós-operatório precoce, a conduta inicial é conservadora (sonda nasogástrica), mas a cirurgia é necessária se houver sofrimento de alça.", "option_rationales": {"a": "Incorreta. No íleo os ruídos estariam ausentes ou diminuídos, não metálicos.", "b": "Correta. Diagnóstico e manejo cirúrgico padrão para obstrução alta.", "c": "Incorreta. Deiscência causaria peritonite, febre e queda do estado geral.", "d": "Incorreta. Isquemia causaria dor desproporcional ao exame físico e acidose metabólica precoce.", "e": "Incorreta. Clostridium causa diarreia profusa, não obstrução."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Obstrução Intestinal", "Clínica Cirúrgica"]}', 17, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório imediato de um paciente submetido a paratireoidectomia por hiperparatireoidismo secundário à insuficiência renal crônica, observa-se queda brusca dos valores de cálcio sérico (Ca: 6,8 mg/dL) apesar da função adequada das glândulas remanescentes suspeitada pelo cirurgião. O paciente apresenta cãibras e parestesias. Qual o nome deste fenômeno e a causa provável?", "options": {"a": "Síndrome do Osso Faminto (Hungry Bone Syndrome); deposição rápida de cálcio e fósforo no osso após queda do PTH elevado.", "b": "Hipoparatiroidismo definitivo por lesão vascular acidental do pedículo tireoidiano.", "c": "Pancreatite aguda pós-operatória por manipulação cirúrgica.", "d": "Acidose metabólica causando redução do cálcio iônico.", "e": "Falta de suplementação de Vitamina C no peroperatório."}, "answer": "a", "rationale": "A ''Hungry Bone Syndrome'' ocorre em pacientes com hiperparatiroidismo severo de longa data. Com a queda rápida do PTH após a cirurgia, o osso ávido por cálcio retira o mineral do sangue rapidamente, causando hipocalcemia severa.", "option_rationales": {"a": "Correta. Fenômeno conhecido em cirurgia endócrina.", "b": "Incorreta. Seria o diagnóstico se as glândulas fossem removidas ou isquemiadas, mas no renal crônico a causa metabólica óssea é muito mais comum.", "c": "Incorreta. Não há nexo causal direto com paratireoidectomia.", "d": "Incorreta. A acidose aumenta a fração iônica do cálcio, não o contrário.", "e": "Incorreta. Vitamina C não tem papel no metabolismo agudo do cálcio."}, "difficulty": "media", "tags": ["Cirurgia Endócrina", "Pós-operatório", "Hipocalcemia", "Osso Faminto"]}', 18, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um homem de 70 anos em 3º DPO de uma herniorrafia inguinal aberta queixa-se de dor escrotal intensa à direita, com aumento de volume e coloração azulada da pele do escroto. Ao exame: testículo direito aumentado, endurecido e extremamente doloroso ao toque. O cirurgião suspeita de orquite isquêmica por trombose do plexo pampiniforme. Qual o fator técnico transoperatório mais associado a esta complicação?", "options": {"a": "Uso de tela de polipropileno de poro pequeno.", "b": "Dissecção excessiva e agressiva do cordão espermático e do saco herniário na região do canal inguinal.", "c": "Sutura do anel inguinal interno muito frouxa.", "d": "Não fechamento da fáscia de Scarpa.", "e": "Uso de anestesia raquidiana em vez de anestesia local."}, "answer": "b", "rationale": "A orquite isquêmica ocorre pela lesão ou trombose das veias do plexo pampiniforme devido a trauma cirúrgico durante a dissecção do cordão. Pode levar à atrofia testicular.", "option_rationales": {"a": "Incorreta. A tela pode causar dor crônica, mas a isquemia é por trauma vascular agudo.", "b": "Correta. Principal causa de complicação testicular em herniorrafias.", "c": "Incorreta. Frouxa causaria recidiva.", "d": "Incorreta. Scarpa é subcutânea, sem relação com testículo.", "e": "Incorreta. A técnica anestésica não influencia a isquemia local traumática."}, "difficulty": "moderada", "tags": ["Cirurgia Geral", "Pós-operatório", "Herniorrafia", "Complicações Locais"]}', 19, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Paciente submetido a nefrectomia parcial para tumor renal por via laparoscópica. No 2º DPO, apresenta drenagem de líquido límpido pálido pelo dreno lombar (débito de 400 ml/dia). A análise desse líquido revela creatinina de 25 mg/dL (creatinina sérica de 1,1 mg/dL). Com base neste resultado, o diagnóstico e o manejo inicial adequado são:", "options": {"a": "Fístula urinária (urinoma); manutenção do dreno e, se necessário, inserção de duplo J.", "b": "Seroma lombar estéril; retirada imediata do dreno por risco de infecção.", "c": "Linfonodomegália iatrogênica (ascite quilosa); dieta com baixo teor de gordura.", "d": "Sangramento ativo silencioso; reoperação imediata.", "e": "Fístula entérica; antibioticoterapia e jejum."}, "answer": "a", "rationale": "A creatinina no líquido de drenagem significativamente maior que a sérica confirma a presença de urina (urinoma/fístula ureteral ou calicial). O tratamento consiste em drenagem adequada e derivação urinária (cateter duplo J) para reduzir a pressão no local da fístula.", "option_rationales": {"a": "Correta. A relação de creatinina dreno/soro é diagnóstica.", "b": "Incorreta. Seroma teria creatinina igual à do soro.", "c": "Incorreta. Ascite quilosa teria triglicerídeos altos.", "d": "Incorreta. Líquido límpido afasta hemorragia ativa.", "e": "Incorreta. Fístula entérica teria amilase ou conteúdo bilioso/fecalóide."}, "difficulty": "moderada", "tags": ["Urologia", "Pós-operatório", "Fístula Urinária", "Urinoma"]}', 20, 'draft')
